"""PL-03 step 3: maximum drawdown per ticker."""

from __future__ import annotations

import math
from itertools import accumulate

from risk.types import Drawdown, Returns


def max_drawdown(returns: Returns) -> tuple[Drawdown, ...]:
    """The deepest fall below the running peak, with its peak and trough dates (RISK-05).

    Wealth starts at 1 on `base_date`; ties keep the first peak and the first trough.
    """
    dates = (returns.base_date, *returns.dates)
    return tuple(
        _drawdown(ticker, dates, returns.values[ticker]) for ticker in returns.tickers
    )


def _drawdown(ticker: str, dates: tuple[str, ...], log_returns: tuple[float, ...]) -> Drawdown:
    """Worst fall of the cumulative log level (0 on `dates[0]`) below its running peak."""
    worst = 0.0
    peak, peak_at = 0.0, 0
    worst_peak_at, worst_trough_at = 0, 0
    for at, level in enumerate(accumulate(log_returns), start=1):
        if level > peak:
            peak, peak_at = level, at
        elif level - peak < worst:
            worst, worst_peak_at, worst_trough_at = level - peak, peak_at, at
    return Drawdown(
        ticker=ticker,
        depth=math.expm1(worst),
        peak_date=dates[worst_peak_at],
        trough_date=dates[worst_trough_at],
    )

