def test_worst_fall_carries_its_peak_and_trough_dates():
    # Levels: 01-02 0.1 (peak), 01-03 -0.2 (trough), 01-04 0.3, 01-05 0.2.
    (drawdown,) = max_drawdown(_returns({"ABC": (0.1, -0.3, 0.5, -0.1)}))
    assert (drawdown.peak_date, drawdown.trough_date) == ("2024-01-02", "2024-01-03")


